  "recovered_c": "uint64_t fn_11(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return 0x1D35;\n  }\n  uint64_t hash = 0x1D35;\n  for (size_t i = 0; i < len; i++) {\n    hash = (uint64_t)in[i] + hash * 0x29;\n  }\n  return hash;\n}"
